:root {
  --parchment: #f2e8d5;
  --parchment-dark: #e0cfa8;
  --ink: #2c1f0e;
  --ink-light: #5a3e22;
  --rust: #8b3a1a;
  --rust-light: #c4622d;
  --sage: #4a5e3a;
  --sage-light: #7a9460;
  --gold: #b8862a;
  --cream-border: #c9b07a;
}

.falconry-log {
  background-color: var(--parchment);
  border: 2px solid var(--cream-border);
  border-radius: 6px;
  width: 480px;
  padding: 0;
  overflow: hidden;
  font-size: 13px;
  color: var(--ink);
}

.log-header {
  background-color: var(--ink);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
}

.header-emblem {
  font-size: 28px;
  line-height: 1;
}

.header-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
}

.log-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--gold);
  text-transform: uppercase;
}

.log-title {
  font-size: 17px;
  font-weight: 700;
  color: var(--parchment);
  margin: 0;
  line-height: 1.2;
}

.log-date {
  font-size: 11px;
  color: var(--parchment-dark);
}

.log-status {
  background-color: var(--sage);
  color: var(--parchment);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  padding: 4px 8px;
  border-radius: 3px;
  border: 1px solid var(--sage-light);
}

.log-body {
  display: flex;
  gap: 0;
  padding: 0;
}

.bird-panel {
  background-color: var(--parchment-dark);
  border-right: 2px solid var(--cream-border);
  padding: 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 140px;
  flex-shrink: 0;
}

.panel-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--rust);
}

.bird-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--ink);
  line-height: 1.1;
}

.bird-species {
  font-size: 11px;
  font-style: italic;
  color: var(--ink-light);
  margin-bottom: 6px;
}

.bird-stats {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.bird-stats li {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  border-bottom: 1px dashed var(--cream-border);
  padding-bottom: 4px;
}

.stat-key {
  color: var(--ink-light);
}

.stat-val {
  font-weight: 700;
  color: var(--ink);
}

.session-panel {
  flex: 1;
  padding: 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.session-row {
  display: flex;
  gap: 8px;
}

.session-block {
  flex: 1;
  background-color: var(--parchment-dark);
  border: 1px solid var(--cream-border);
  border-radius: 4px;
  padding: 8px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.session-block.highlight {
  background-color: var(--rust);
  border-color: var(--rust-light);
}

.block-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--ink-light);
}

.session-block.highlight .block-label {
  color: var(--parchment-dark);
}

.block-value {
  font-size: 15px;
  font-weight: 700;
  color: var(--ink);
}

.session-block.highlight .block-value {
  color: var(--parchment);
  font-size: 12px;
}

.notes-row {
  background-color: var(--parchment-dark);
  border: 1px solid var(--cream-border);
  border-radius: 4px;
  border-left: 3px solid var(--gold);
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.notes-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--gold);
}

.notes-text {
  font-size: 11px;
  line-height: 1.5;
  color: var(--ink-light);
  margin: 0;
}

.log-footer {
  background-color: var(--ink);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
}

.trainer-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--gold);
}

.trainer-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--parchment);
}

.footer-divider {
  flex: 1;
  height: 1px;
  background-color: var(--ink-light);
}

.footer-cert {
  font-size: 10px;
  color: var(--parchment-dark);
  font-style: italic;
}

.footer-stamp {
  font-size: 10px;
  font-weight: 700;
  color: var(--sage-light);
  border: 1px solid var(--sage);
  padding: 2px 6px;
  border-radius: 2px;
}
